using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Shapes;using ToneCustoms.ShellStudio.Core;
namespace ToneCustoms.ShellStudio.Editor;
public sealed class ViewportControl:Canvas { readonly SceneProjection projection=new();ShellProject? project;Guid? selected;Point? dragStart;Vec3? objectStart;public event Action<Guid>? ObjectSelected;public event Action? ObjectMoved;public ViewportControl(){Background=new SolidColorBrush(Color.FromRgb(12,12,16));ClipToBounds=true;SizeChanged+=(_,_)=>RenderScene();}public void SetProject(ShellProject p,Guid? selectedId=null){project=p;selected=selectedId;RenderScene();}public void RenderScene(){Children.Clear();if(ActualWidth<=0||ActualHeight<=0)return;for(double x=0;x<ActualWidth;x+=35)Children.Add(new Line{X1=x,Y1=0,X2=x,Y2=ActualHeight,Stroke=new SolidColorBrush(Color.FromRgb(30,30,38)),StrokeThickness=1});for(double y=0;y<ActualHeight;y+=35)Children.Add(new Line{X1=0,Y1=y,X2=ActualWidth,Y2=y,Stroke=new SolidColorBrush(Color.FromRgb(30,30,38)),StrokeThickness=1});if(project==null)return;foreach(var p in projection.TopDown(project,35,ActualWidth/2,ActualHeight/2)){var active=selected==p.Id;var r=new Rectangle{Width=p.Width,Height=p.Height,Fill=new SolidColorBrush(active?Color.FromArgb(190,126,87,220):Color.FromArgb(145,94,65,170)),Stroke=new SolidColorBrush(active?Color.FromRgb(230,215,255):Color.FromRgb(170,145,230)),StrokeThickness=active?3:1.5,ToolTip=p.Name,Tag=p.Id};r.MouseLeftButtonDown+=Down;r.MouseMove+=Move;r.MouseLeftButtonUp+=Up;Canvas.SetLeft(r,p.Left);Canvas.SetTop(r,p.Top);Children.Add(r);}}void Down(object s,MouseButtonEventArgs e){if(s is FrameworkElement f&&f.Tag is Guid id&&project!=null){selected=id;ObjectSelected?.Invoke(id);var o=project.Objects.FirstOrDefault(x=>x.Id==id);if(o!=null){dragStart=e.GetPosition(this);objectStart=new(o.Position.X,o.Position.Y,o.Position.Z);f.CaptureMouse();}e.Handled=true;}}void Move(object s,MouseEventArgs e){if(dragStart==null||objectStart==null||project==null||selected==null||e.LeftButton!=MouseButtonState.Pressed)return;var now=e.GetPosition(this);var o=project.Objects.FirstOrDefault(x=>x.Id==selected);if(o==null)return;var dx=(float)((now.X-dragStart.Value.X)/35.0);var dy=(float)(-(now.Y-dragStart.Value.Y)/35.0);var grid=project.Settings.GridSize;o.Position=new(Snap(objectStart.X+dx,grid),Snap(objectStart.Y+dy,grid),objectStart.Z);RenderScene();ObjectMoved?.Invoke();}void Up(object s,MouseButtonEventArgs e){dragStart=null;objectStart=null;if(s is UIElement u)u.ReleaseMouseCapture();}static float Snap(float v,float g)=>g<=0?v:MathF.Round(v/g)*g; }
